// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { mergeTriples, withLoadedTypes } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";

const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const uri = (value) => ({ type: "uri", value });
const row = (source, predicate, target) => ({ source: uri(source), predicate: uri(predicate), target: uri(target) });

test("loaded rdf:type statements give nodes their types without asking the repository", () => {
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([row("urn:a", RDF_TYPE, "urn:Person"), row("urn:a", RDF_TYPE, "urn:Agent"), row("urn:a", "urn:knows", "urn:b")]),
  );
  const typed = withLoadedTypes(graph);
  const a = typed.nodes.find((node) => node.id === "urn:a");
  assert.deepEqual(a.types.map((type) => type.id), ["urn:Person", "urn:Agent"]);
  assert.equal(typed.nodes.find((node) => node.id === "urn:b").types, undefined, "b's types are still to be asked for");
  assert.equal(withLoadedTypes(typed), typed, "nothing new: the same graph");
});

test("types already known keep their labels and gain the newly loaded ones", () => {
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([row("urn:a", RDF_TYPE, "urn:Agent")]),
  );
  const known = { ...graph, nodes: graph.nodes.map((node) => (node.id === "urn:a" ? { ...node, types: [{ id: "urn:Person", label: "Person" }] } : node)) };
  const typed = withLoadedTypes(known);
  assert.deepEqual(typed.nodes.find((node) => node.id === "urn:a").types.map((type) => [type.id, type.label]), [["urn:Person", "Person"], ["urn:Agent", "Agent"]]);
});

test("a blank node a resource is typed with is not taken as its type", () => {
  // An anonymous OWL class: the type lookup asks for IRI types only, and so does the graph.
  const blank = (value, extra) => ({ type: "bnode", value, ...extra });
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([
      { source: uri("urn:a"), predicate: uri(RDF_TYPE), target: blank("restriction", { "rdf4j:reference": true }) },
      { source: uri("urn:b"), predicate: uri(RDF_TYPE), target: blank("b0", { "rdf4j:scope": "response:1" }) },
      row("urn:b", RDF_TYPE, "urn:Person"),
    ]),
  );
  const typed = withLoadedTypes(graph);
  assert.equal(typed.nodes.find((node) => node.id === "urn:a").types, undefined);
  assert.deepEqual(typed.nodes.find((node) => node.id === "urn:b").types.map((type) => type.id), ["urn:Person"]);
});
